  headingMain: "\u098F\u0995\u099F\u09BF \u09A4\u09CD\u09B0\u09C1\u099F\u09BF\u09B0 \u09B8\u09AE\u09CD\u09AE\u09C1\u0996\u09C0\u09A8 \u09B9\u09AF\u09BC\u09C7\u099B\u09C7\u09F7 \u099A\u09C7\u09B7\u09CD\u099F\u09BE \u0995\u09B0\u09C1\u09A8 <button>\u09AA\u09C3\u09B7\u09CD\u09A0\u09BE\u099F\u09BF \u09AA\u09C1\u09A8\u09B0\u09BE\u09AF\u09BC \u09B2\u09CB\u09A1 \u0995\u09B0\u09BE\u09B0\u0964</button>",
