  button_stopSession: "\u09B8\u09C7\u09B6\u09A8 \u09AC\u09A8\u09CD\u09A7 \u0995\u09B0\u09C1\u09A8",
  desc_inProgressIntro: "\u09B2\u09BE\u0987\u09AD-\u09B8\u09B9\u09AF\u09CB\u0997\u09C0\u09A4\u09BE\u09B0 \u09B8\u09C7\u09B6\u09A8 \u098F\u0996\u09A8 \u099A\u09B2\u099B\u09C7\u0964",
